create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,organisation text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.sites(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),name text not null,operator text,country text,region text,commodity text,total_area numeric,disturbed_area numeric,rehabilitation_target_area numeric,stage text,start_date date,target_completion_date date,site_manager text,description text,archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.assessments(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),site_id uuid references public.sites(id) on delete cascade,assessment_type text not null,assessor text,assessment_date date,land_stability_score numeric check(land_stability_score between 0 and 100),erosion_score numeric check(erosion_score between 0 and 100),soil_condition_score numeric check(soil_condition_score between 0 and 100),vegetation_score numeric check(vegetation_score between 0 and 100),water_drainage_score numeric check(water_drainage_score between 0 and 100),biodiversity_score numeric check(biodiversity_score between 0 and 100),safety_score numeric check(safety_score between 0 and 100),compliance_score numeric check(compliance_score between 0 and 100),overall_score numeric generated always as ((coalesce(land_stability_score,0)+coalesce(erosion_score,0)+coalesce(soil_condition_score,0)+coalesce(vegetation_score,0)+coalesce(water_drainage_score,0)+coalesce(biodiversity_score,0)+coalesce(safety_score,0)+coalesce(compliance_score,0))/8) stored,observations text,recommended_actions text,status text not null default 'Draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.rehabilitation_actions(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),site_id uuid references public.sites(id) on delete cascade,assessment_id uuid references public.assessments(id) on delete set null,title text not null,category text,description text,responsible_person text,priority text,start_date date,due_date date,completion_date date,budget numeric,progress numeric not null default 0 check(progress between 0 and 100),status text not null default 'Planned',verification_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),site_id uuid references public.sites(id) on delete cascade,report_type text,period_start date,period_end date,content jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ai_conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),site_id uuid references public.sites(id) on delete cascade,messages jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; expr text; begin foreach t in array array['profiles','sites','assessments','rehabilitation_actions','reports','ai_conversations'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "owner access" on public.%I',t);expr:=case when t='profiles' then 'id = auth.uid()' else 'user_id = auth.uid()' end;execute format('create policy "owner access" on public.%I for all to authenticated using (%s) with check (%s)',t,expr,expr);end loop;end $$;
